std::stack<char> st;
std::unordered_map<char,char> mp{{')','('}, {']','['}, {'}','{'}};
for (char c : s) {
    if (c == '(' || c == '[' || c == '{') {
        st.push(c);
    } else if (mp.count(c)) {
        if (st.empty() || st.top() != mp[c]) return false;
        st.pop();
    }
}
return st.empty();      // 必须为空

std::vector<int> nge(n, -1);      // 默认无更大元素
std::stack<int> st;               // 存下标
for (int i = 0; i < n; ++i) {
    while (!st.empty() && a[st.top()] < a[i]) {
        nge[st.top()] = a[i];     // 找到了
        st.pop();
    }
    st.push(i);
}

std::deque<int> dq;               // 存下标
std::vector<int> res;
for (int i = 0; i < n; ++i) {
    // 1. 队尾弹出比当前小的
    while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
    dq.push_back(i);
    // 2. 队首滑出窗口则弹出
    if (dq.front() <= i - k) dq.pop_front();
    // 3. 窗口成形后记录
    if (i >= k - 1) res.push_back(a[dq.front()]);
}

void push(int x) { in.push(x); }

int pop() {
    if (out.empty()) {
        while (!in.empty()) {      // 一次性倒完
            out.push(in.top());
            in.pop();
        }
    }
    int v = out.top();
    out.pop();
    return v;
}
